for _, name := range []string{"a", "b"} {
	workers.Add(1)
	go func(name string) {
		defer workers.Done()
		value, err := client.Get(workCtx, name)
		select {
		case results <- fetchResult{value: value, err: err}:
		case <-workCtx.Done():
		}
	}(name)
}

values := make([]string, 0, 2)
for range 2 {
	select {
	case <-ctx.Done():
		cancel()
		workers.Wait()
		return nil, ctx.Err()
	case result := <-results:
		if err := ctx.Err(); err != nil {
			cancel()
			workers.Wait()
			return nil, err
		}
		if result.err != nil {
			cancel()
			workers.Wait()
			return nil, result.err
		}
		values = append(values, result.value)
	}
}

	if err := ctx.Err(); err != nil {
		cancel()
		workers.Wait()
		return nil, err
	}
	workers.Wait()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	return values, nil
}

